// @pit: {"label": "Update action.yml, README, docs/models.md, how-it-works, extensions docs, defaults test"}
async ({ workspace: { read, edit } }) => {
  const rep = async (file: string, pairs: [string, string][]) => {
    const r = await read(file, { format: "raw" });
    let c = r.content;
    for (const [a, b] of pairs) {
      if (!c.includes(a)) throw new Error(`${file}: missing ${a.slice(0, 60)}`);
      c = c.replace(a, b);
    }
    await edit(file, { revision: r.revision, changes: [{ kind: "replaceFile", content: c }] });
  };
  await rep("action.yml", [
    [`    default: 'claude-sonnet-5-5'\n`, `    default: 'claude-sonnet-5-5'\n  thinking_level:\n    description: 'How much the model thinks before it answers: off, minimal, low, medium, high, xhigh, or max. A model that does not support the level gets the nearest level it supports (off without reasoning support), with a log line'\n    required: false\n    default: 'medium'\n`],
    [`        INPUT_MODEL: \${{ inputs.model }}\n`, `        INPUT_MODEL: \${{ inputs.model }}\n        INPUT_THINKING_LEVEL: \${{ inputs.thinking_level }}\n`],
  ]);
  await rep("README.md", [
    ["| `model` | Model ID | No | `claude-sonnet-5-5` |\n", "| `model` | Model ID | No | `claude-sonnet-5-5` |\n| `thinking_level` | How much the model thinks before it answers: `off`, `minimal`, `low`, `medium`, `high`, `xhigh`, or `max`. A model that does not support the level gets the nearest level that it supports, and a model without reasoning support gets `off` (see [Thinking](docs/models.md#thinking)) | No | `medium` |\n"],
    ["| `model_reasoning` | The custom model supports reasoning (thinking) | No | `false` |", "| `model_reasoning` | The custom model supports reasoning (thinking). When `false`, the model gets `thinking_level: off` | No | `false` |"],
  ]);
  await rep("docs/models.md", [
    [`## Providers from pi extensions`, `## Thinking

\`thinking_level\` sets how much the model thinks (reasons) before it answers. The default is \`medium\`, as in pi. A higher level can give better answers to difficult tasks, but it uses more tokens and more time. To turn thinking off, set \`off\`:

\`\`\`yaml
with:
  thinking_level: off   # or minimal, low, medium, high, xhigh, max
\`\`\`

- **Every run.** pi-action sets the level at the start of each run. A thread that started with a different level uses the new level from the next run, as it does for \`model\`.
- **Models that support less.** pi-action caps the level as pi does (pi-ai's \`clampThinkingLevel\`), and writes a log line, for example \`thinking_level: openai/gpt-4o has no reasoning support; using off\`:
  - A model without reasoning support gets \`off\`. pi knows this for its built-in models. For a custom model, set \`model_reasoning: true\` when the model supports reasoning.
  - \`xhigh\` and \`max\` apply only to the models that pi maps to them. Other reasoning models get \`high\`.
  - For other levels that a model does not support, it gets the next level up that it supports, else the next level down.
- **How the level gets to the model.** The provider API changes the level into its own option. For example, Anthropic gets a thinking budget, or an effort with \`compat_force_adaptive_thinking\`. OpenAI-compatible APIs get a reasoning effort when the provider supports it (\`compat_supports_reasoning_effort\`).
- **Output tokens.** Thinking counts toward the output tokens of the model (\`model_max_tokens\` for a custom model).

The \`🤖\` line of the log shows the level of the run, for example \`🤖 anthropic/claude-sonnet-5-5 · thinking medium · tools: read, write, edit, bash\`.

## Providers from pi extensions`],
  ]);
  await rep("docs/how-it-works.md", [
    ["🤖 nvidia/aws/anthropic/bedrock-claude-opus-5-5 · tools:", "🤖 nvidia/aws/anthropic/bedrock-claude-opus-5-5 · thinking medium · tools:"],
    ["| `🤖` | The model, the tools that it gets", "| `🤖` | The model, its thinking level (see [Thinking](models.md#thinking)), the tools that it gets"],
  ]);
  await rep("docs/extensions.md", [
    ["`🤖 anthropic/claude-sonnet-5-5 · tools: typescript · extensions: pit (typescript)`", "`🤖 anthropic/claude-sonnet-5-5 · thinking medium · tools: typescript · extensions: pit (typescript)`"],
  ]);
  await rep("src/defaults.test.ts", [
    [`	["model", DEFAULTS.model],\n`, `	["model", DEFAULTS.model],\n	["thinking_level", DEFAULTS.thinkingLevel],\n`],
  ]);
  return "ok";
}
